-- ISO 9001:2026 quality-management-system gap assessment.
-- Original audit prompts and implementation guidance; this content does not reproduce
-- or replace the licensed standard. Annex A guidance is informative and is not scored.

alter table public.assessment_questions add column if not exists practical_application text;
alter table public.assessment_questions add column if not exists applicability_guidance text;
alter table public.assessment_questions add column if not exists documented_information_guidance text;
alter table public.assessment_questions add column if not exists related_requirements text;

create table if not exists public.assessment_annex_guidance (
  id uuid primary key default gen_random_uuid(), standard text not null,
  reference text not null, title text not null, guidance text not null,
  display_order integer not null default 0, scored boolean not null default false,
  unique (standard, reference)
);

delete from public.assessment_questions where standard='ISO 9001:2026';
