$requirements$::jsonb) as x(o integer,n text,c text,r text,q text,s text,e text,p text,a text,d text,i text,w text)
)
insert into public.assessment_questions
(standard,question_number,clause,clause_reference,question,requirement_summary,
 practical_application,applicability_guidance,documented_information_guidance,
 assessor_guidance,interview_questions,objective_evidence,sampling_guidance,
 conformity_criteria,minor_nc_guidance,major_nc_guidance,management_focus,
 related_requirements,active,display_order)
select 'ISO 9001:2026',n,c,r,q,s,p,a,d,
 'Evaluate design, implementation and effectiveness. Triangulate controlled information, interviews, observation and results; a document alone is not evidence of effective implementation.',
 i,e,
 case when c='8' then 'Use risk-based end-to-end trails across representative products/services, sites, shifts, changes and external providers; include at least one exception or nonconforming output.' when c in ('5','9') then 'Sample leadership and process-owner decisions across more than one reporting period and corroborate minutes with results and completed actions.' else 'Sample relevant functions, locations, roles and periods; trace normal operation, recent change and exception where risk warrants.' end,
 'Current, approved and representative evidence demonstrates scope-wide implementation, accountable ownership, reliable results, review and effective action.',
 'An isolated lapse exists, while objective evidence shows the process remains substantially implemented and effective without systemic loss of control.',
 'The requirement is absent, materially ineffective or systemically uncontrolled, or the weakness creates significant doubt about conformity, customer outcomes or QMS effectiveness.',
 case when c='5' then 'Evaluate visible leadership behaviour, ethical decisions and quality culture.' when c='8' then 'Evaluate process capability, interfaces, change, external provision and customer impact.' when c='9' then 'Evaluate data reliability, challenge, decisions and action follow-through.' else 'Connect the requirement to strategy, process ownership, customer outcomes and improvement.' end,
 w,true,o from requirements;

delete from public.assessment_annex_guidance where standard='ISO 9001:2026';
insert into public.assessment_annex_guidance(standard,reference,title,guidance,display_order,scored) values
('ISO 9001:2026','A.1','Purpose and use','Use Annex A to interpret intent consistently. It is informative, adds no requirements and must not be scored as a separate conformity criterion.',1,false),
('ISO 9001:2026','A.2','Structure and terminology','Do not require organisations to use the standard’s clause sequence or terminology. Evaluate whether their process system achieves the required outcomes.',2,false),
('ISO 9001:2026','A.3','Products and services','Apply requirements according to the organisation’s actual products and services, including service-specific evidence and customer interfaces.',3,false),
('ISO 9001:2026','A.4','Risk and opportunity','Evaluate risks and opportunities as distinct concepts and test whether proportionate actions are integrated and effective.',4,false),
('ISO 9001:2026','A.5','Applicability','Accept a non-applicability decision only when it is factually supported and does not compromise conformity or customer satisfaction.',5,false),
('ISO 9001:2026','A.6','Documented information','Do not prescribe unnecessary documents. Evaluate whether maintained and retained information is sufficient for effective operation and confidence in results.',6,false),
('ISO 9001:2026','A.7','Organisational knowledge and improvement','Evaluate how knowledge, learning, quality culture, change and improvement support sustained QMS effectiveness.',7,false);

do $profile$ declare profile_id uuid; begin
 update public.scoring_profiles set active=false where standard='ISO 9001:2026';
 insert into public.scoring_profiles(standard,profile_name,version_label,active)
 values('ISO 9001:2026','RPG ISO 9001:2026 evidence-led executive readiness','2026 v2',true) returning id into profile_id;
 insert into public.scoring_profile_clauses(scoring_profile_id,clause,weight) values
 (profile_id,'4',10),(profile_id,'5',15),(profile_id,'6',12),(profile_id,'7',12),(profile_id,'8',25),(profile_id,'9',16),(profile_id,'10',10);
end $profile$;
